let user = {
  name: "Alex",
  greet() {
    console.log("Hello, " + this.name);
  }
};

user.greet();  // "Hello, Alex" — this = user

// Lost binding
let greet = user.greet;
greet();  // "Hello, undefined" — this = global object

function greet(greeting) {
  console.log(greeting + ", " + this.name + "!");
}

let user = { name: "Alex" };

// call — immediate, individual args
greet.call(user, "Hello");  // "Hello, Alex!"

// apply — immediate, array of args
greet.apply(user, ["Hi"]);  // "Hi, Alex!"

// bind — returns new function with 'this' fixed
let boundGreet = greet.bind(user);
boundGreet("Hey");  // "Hey, Alex!"
boundGreet("Yo");   // "Yo, Alex!"

function User(name, age) {
  this.name = name;
  this.age = age;
  this.greet = function() {
    console.log("Hi, I'm " + this.name);
  };
}

let alex = new User("Alex", 25);
let sam = new User("Sam", 30);

alex.greet();  // "Hi, I'm Alex"
sam.greet();   // "Hi, I'm Sam"

console.log(alex instanceof User);  // true

let user = {
  name: "Alex",
  hobbies: ["reading", "coding", "gaming"],

  // Regular method — loses 'this' in callbacks
  showHobbiesOld() {
    this.hobbies.forEach(function(hobby) {
      console.log(this.name + " likes " + hobby);
    });
  },

  // Arrow method — 'this' is preserved
  showHobbiesNew() {
    this.hobbies.forEach((hobby) => {
      console.log(this.name + " likes " + hobby);
    });
  }
};

user.showHobbiesOld();  // undefined likes reading (broken!)
user.showHobbiesNew();  // Alex likes reading (correct!)
